package ultra.downloads;
import android.app.*;import android.content.*;import android.content.pm.ProviderInfo;import android.database.*;import android.net.Uri;import android.os.*;import java.io.*;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.ShadowContentResolver;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=28) @LooperMode(LooperMode.Mode.PAUSED)
public class DL28DeleteProviderTest {
 static class AudioProvider extends ContentProvider{
  Set<String> files=new HashSet<>();ArrayList<String> deletes=new ArrayList<>();boolean deny,pretend;
  public boolean onCreate(){return true;}public String getType(Uri u){return "audio/mpeg";}public Uri insert(Uri u,ContentValues v){return null;}public int update(Uri u,ContentValues v,String q,String[] a){return 0;}
  public Cursor query(Uri u,String[] projection,String q,String[] args,String sort){MatrixCursor c=new MatrixCursor(new String[]{"_id"});if(files.contains(u.toString()))c.addRow(new Object[]{1});return c;}
  public int delete(Uri u,String q,String[] a){deletes.add(u.toString());if(deny)throw new SecurityException("denied");if(pretend)return 0;return files.remove(u.toString())?1:0;}
 }
 Activity c;AudioProvider provider;
 @Before public void setup()throws Exception{c=Robolectric.buildActivity(Activity.class).setup().get();app.revanced.extension.shared.utils.Utils.testContext=c;java.lang.reflect.Field f=Library.class.getDeclaredField("items");f.setAccessible(true);f.set(null,null);new File(c.getFilesDir(),"ultra_downloads_v1.json").delete();Library.wiping=false;provider=new AudioProvider();ProviderInfo info=new ProviderInfo();info.authority="media";provider.attachInfo(c,info);ShadowContentResolver.registerProviderInternal("media",provider);}
 Library.Item imported(String id,int number)throws Exception{Library.Item i=Library.add(c,id,"Imported "+number);i.imported=true;i.uri="content://media/external/audio/media/"+number;i.state="done";provider.files.add(i.uri);Library.save(c);return i;}
 void await(PermanentDelete d)throws Exception{for(int n=0;n<100&&d.busy;n++){Thread.sleep(20);Shadows.shadowOf(Looper.getMainLooper()).idle();}Shadows.shadowOf(Looper.getMainLooper()).idle();assertFalse(d.busy);}
 @Test public void onlySelectedImportedUriIsDeleted()throws Exception{Library.Item selected=imported("abcdefghijk",11),other=imported("lmnopqrstuv",22);PermanentDelete d=new PermanentDelete(c,c,Arrays.asList(selected),()->{});assertTrue(provider.deletes.isEmpty());d.start();await(d);assertEquals(Arrays.asList(selected.uri),provider.deletes);assertFalse(provider.files.contains(selected.uri));assertTrue(provider.files.contains(other.uri));assertNull(Library.get(c,selected.id));assertNotNull(Library.get(c,other.id));}
 @Test public void deniedImportedDeleteKeepsFileAndRecord()throws Exception{Library.Item i=imported("abcdefghijk",11);provider.deny=true;PermanentDelete d=new PermanentDelete(c,c,Arrays.asList(i),()->{});d.start();await(d);assertEquals(0,d.deleted);assertEquals(1,d.failed);assertTrue(provider.files.contains(i.uri));assertNotNull(Library.get(c,i.id));}
 @Test public void zeroRowsIsNotSuccessWhenFileStillExists()throws Exception{Library.Item i=imported("abcdefghijk",11);provider.pretend=true;PermanentDelete d=new PermanentDelete(c,c,Arrays.asList(i),()->{});d.start();await(d);assertEquals(0,d.deleted);assertEquals(1,d.failed);assertNotNull(Library.get(c,i.id));}
 @Test public void systemConsentSuccessVerifiesAbsenceWithoutDeletingAgain()throws Exception{Library.Item i=imported("abcdefghijk",11);PermanentDelete d=new PermanentDelete(c,c,Arrays.asList(i),()->{});d.waiting=d.busy=d.systemDeleted=true;provider.files.remove(i.uri);d.result(Activity.RESULT_OK);await(d);assertEquals(1,d.deleted);assertTrue(provider.deletes.isEmpty());assertNull(Library.get(c,i.id));}
 @Test public void systemConsentCannotFalselyRemoveKeptFile()throws Exception{Library.Item i=imported("abcdefghijk",11);PermanentDelete d=new PermanentDelete(c,c,Arrays.asList(i),()->{});d.waiting=d.busy=d.systemDeleted=true;d.result(Activity.RESULT_OK);await(d);assertEquals(0,d.deleted);assertNotNull(Library.get(c,i.id));assertTrue(provider.files.contains(i.uri));}
}
